#!/usr/bin/env node

/**
 * UAT Storage Reset Script
 * Cleans Storage buckets using Supabase Storage API
 * NEVER use DELETE FROM storage.objects directly
 *
 * Usage:
 *   node scripts/uat-reset-storage.mjs --dry-run
 *   node scripts/uat-reset-storage.mjs --execute
 *
 * Author: Generated by Claude Code
 * Date: 2026-08-31
 */

import { createClient } from '@supabase/supabase-js'
import { loadEnv, validateEnv, maskApiKey } from './lib/load-env.mjs'

// Load environment variables
loadEnv()

// Validate required variables
const config = validateEnv({ requireSupabase: true })

// ============================================================================
// CONFIGURATION
// ============================================================================

const SUPABASE_URL = config.supabaseUrl
const SUPABASE_SERVICE_ROLE_KEY = config.serviceRoleKey

const BUCKETS = ['ticket-evidences', 'ticket-signatures']

const DRY_RUN = process.argv.includes('--dry-run')
const EXECUTE = process.argv.includes('--execute')

// ============================================================================
// VALIDATION
// ============================================================================

if (!DRY_RUN && !EXECUTE) {
  console.error('❌ ERROR: Must specify --dry-run or --execute')
  console.error('')
  console.error('Usage:')
  console.error('  node scripts/uat-reset-storage.mjs --dry-run')
  console.error('  node scripts/uat-reset-storage.mjs --execute')
  process.exit(1)
}

if (DRY_RUN && EXECUTE) {
  console.error('❌ ERROR: Cannot specify both --dry-run and --execute')
  process.exit(1)
}

// ============================================================================
// SUPABASE CLIENT (SERVICE ROLE - SERVER SIDE ONLY)
// ============================================================================

const supabase = createClient(SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY, {
  auth: {
    autoRefreshToken: false,
    persistSession: false,
  },
})

// ============================================================================
// HELPER FUNCTIONS
// ============================================================================

/**
 * Recursively list all REAL FILES in a bucket
 * Supabase Storage uses folder-like prefixes, but list('') only returns top-level
 * We need to recurse into each prefix to get actual files
 * @param {string} bucketId - Bucket name
 * @param {string} prefix - Current prefix/folder (empty string for root)
 * @returns {Promise<string[]>} Array of full file paths
 */
async function listAllFilesRecursive(bucketId, prefix = '') {
  const allFiles = []
  let offset = 0
  const limit = 1000

  while (true) {
    const { data, error } = await supabase.storage
      .from(bucketId)
      .list(prefix, {
        limit,
        offset,
        sortBy: { column: 'name', order: 'asc' },
      })

    if (error) {
      console.error(`❌ Error listing ${bucketId} at prefix "${prefix}":`, error.message)
      throw error
    }

    if (!data || data.length === 0) {
      break
    }

    // Process each item
    for (const item of data) {
      const fullPath = prefix ? `${prefix}/${item.name}` : item.name

      // Check if this is a folder (no metadata.size means it's a prefix/folder)
      // OR check id field - folders typically have null id
      const isFolder = !item.id || item.id === null

      if (isFolder) {
        // Recurse into this folder
        const nestedFiles = await listAllFilesRecursive(bucketId, fullPath)
        allFiles.push(...nestedFiles)
      } else {
        // This is a real file
        allFiles.push(fullPath)
      }
    }

    offset += limit

    if (data.length < limit) {
      break
    }
  }

  return allFiles
}

async function removeObjects(bucketId, paths) {
  if (paths.length === 0) {
    return { success: true, removed: 0 }
  }

  // Batch delete in chunks of 100
  const BATCH_SIZE = 100
  let totalRemoved = 0
  const failedPaths = []

  for (let i = 0; i < paths.length; i += BATCH_SIZE) {
    const batch = paths.slice(i, i + BATCH_SIZE)

    const { data, error } = await supabase.storage
      .from(bucketId)
      .remove(batch)

    if (error) {
      console.error(`❌ Error removing batch from ${bucketId}:`, error.message)
      // Track which paths failed
      failedPaths.push(...batch)
      // Continue with remaining batches instead of throwing
      console.log(`  ⚠️  Batch ${i / BATCH_SIZE + 1} failed, continuing...`)
    } else {
      // Count successfully removed files
      // data is an array of {name: string} for successfully deleted files
      const removedCount = data ? data.length : batch.length
      totalRemoved += removedCount
      console.log(`  Removed ${totalRemoved}/${paths.length} files...`)
    }
  }

  if (failedPaths.length > 0) {
    console.log(`  ⚠️  ${failedPaths.length} files failed to delete`)
    throw new Error(`Failed to delete ${failedPaths.length} files`)
  }

  return { success: true, removed: totalRemoved }
}

// ============================================================================
// MAIN
// ============================================================================

async function main() {
  console.log('='.repeat(80))
  console.log('UAT STORAGE RESET')
  console.log('='.repeat(80))
  console.log('')

  if (DRY_RUN) {
    console.log('🔍 MODE: DRY RUN (no files will be deleted)')
  } else {
    console.log('🔥 MODE: EXECUTE (files WILL BE DELETED)')
  }
  console.log('')

  // ============================================================================
  // 1. LIST ALL REAL FILES RECURSIVELY
  // ============================================================================

  const bucketInventory = {}

  for (const bucketId of BUCKETS) {
    console.log(`📦 Listing files in: ${bucketId}`)

    try {
      const filePaths = await listAllFilesRecursive(bucketId)
      bucketInventory[bucketId] = filePaths

      console.log(`  Found: ${filePaths.length} files`)

      if (filePaths.length > 0 && filePaths.length <= 10) {
        filePaths.forEach(path => {
          console.log(`    - ${path}`)
        })
      } else if (filePaths.length > 10) {
        console.log(`    First 10:`)
        filePaths.slice(0, 10).forEach(path => {
          console.log(`      - ${path}`)
        })
        console.log(`    ... and ${filePaths.length - 10} more`)
      }

      console.log('')
    } catch (error) {
      console.error(`❌ Failed to list ${bucketId}`)
      process.exit(1)
    }
  }

  // ============================================================================
  // 2. SUMMARY
  // ============================================================================

  const totalFiles = Object.values(bucketInventory).reduce(
    (sum, files) => sum + files.length,
    0
  )

  console.log('='.repeat(80))
  console.log('SUMMARY')
  console.log('='.repeat(80))
  console.log('')

  for (const [bucketId, files] of Object.entries(bucketInventory)) {
    console.log(`${bucketId}: ${files.length} files`)
  }

  console.log('')
  console.log(`TOTAL: ${totalFiles} files`)
  console.log('')

  // ============================================================================
  // 3. DRY RUN EXIT
  // ============================================================================

  if (DRY_RUN) {
    console.log('✅ DRY RUN COMPLETE - NO FILES DELETED')
    console.log('')
    console.log('To execute deletion, run:')
    console.log('  node scripts/uat-reset-storage.mjs --execute')
    console.log('')
    process.exit(0)
  }

  // ============================================================================
  // 4. EXECUTE DELETION
  // ============================================================================

  console.log('⚠️  WARNING: About to DELETE all objects')
  console.log('')

  // Safety check - require explicit confirmation env var
  if (process.env.UAT_RESET_CONFIRMED !== 'yes') {
    console.error('❌ ABORT: UAT_RESET_CONFIRMED environment variable not set')
    console.error('')
    console.error('To confirm deletion, run:')
    console.error('  UAT_RESET_CONFIRMED=yes node scripts/uat-reset-storage.mjs --execute')
    console.error('')
    process.exit(1)
  }

  console.log('🔥 Starting deletion...')
  console.log('')

  for (const [bucketId, filePaths] of Object.entries(bucketInventory)) {
    if (filePaths.length === 0) {
      console.log(`⏭️  ${bucketId}: No files to delete`)
      continue
    }

    console.log(`🗑️  Deleting from ${bucketId} (${filePaths.length} files)...`)

    try {
      const result = await removeObjects(bucketId, filePaths)
      console.log(`  ✅ Removed ${result.removed} files from ${bucketId}`)
      console.log('')
    } catch (error) {
      console.error(`❌ Failed to delete from ${bucketId}`)
      process.exit(1)
    }
  }

  // ============================================================================
  // 5. VERIFY
  // ============================================================================

  console.log('='.repeat(80))
  console.log('VERIFICATION')
  console.log('='.repeat(80))
  console.log('')

  for (const bucketId of BUCKETS) {
    console.log(`🔍 Verifying ${bucketId}...`)

    const filePaths = await listAllFilesRecursive(bucketId)
    const count = filePaths.length

    if (count === 0) {
      console.log(`  ✅ PASS: 0 files remaining`)
    } else {
      console.log(`  ❌ FAIL: ${count} files still exist`)
      if (count <= 10) {
        console.log(`  Remaining files:`)
        filePaths.forEach(path => console.log(`    - ${path}`))
      } else {
        console.log(`  First 10 remaining files:`)
        filePaths.slice(0, 10).forEach(path => console.log(`    - ${path}`))
      }
      console.log('')
      console.log('ERROR: Verification failed - some files remain')
      process.exit(1)
    }
  }

  console.log('')
  console.log('='.repeat(80))
  console.log('✅ STORAGE RESET COMPLETE')
  console.log('='.repeat(80))
  console.log('')
  console.log('All Storage objects have been deleted.')
  console.log('Buckets and policies remain intact.')
  console.log('')
}

main().catch(error => {
  console.error('❌ Fatal error:', error.message)
  process.exit(1)
})
